<?php
if (!defined('ABSPATH')) exit;
final class SEO_Manager_Social {public static function init():void{}public static function output(int $id):void{if((int)seom_get('enable_og',1)){foreach([['og:title',seom_meta($id,'og_title',seom_get('og_default_title','')?:seom_title_for_post($id))],['og:description',seom_meta($id,'og_description',seom_get('og_default_description','')?:seom_desc_for_post($id))],['og:url',get_permalink($id)],['og:type',is_singular('post')?'article':'website'],['og:site_name',get_bloginfo('name')]] as $m)echo '<meta property="'.esc_attr($m[0]).'" content="'.esc_attr($m[1]).'">' . "\n";$img=seom_meta($id,'og_image',get_the_post_thumbnail_url($id,'full')?:seom_default_image());if($img)echo '<meta property="og:image" content="'.esc_url($img).'">' . "\n";}if((int)seom_get('enable_twitter',1)){echo '<meta name="twitter:card" content="'.esc_attr(seom_get('twitter_card','summary_large_image')).'">' . "\n";echo '<meta name="twitter:title" content="'.esc_attr(seom_meta($id,'og_title',seom_get('og_default_title','')?:seom_title_for_post($id))).'">' . "\n";echo '<meta name="twitter:description" content="'.esc_attr(seom_meta($id,'og_description',seom_get('og_default_description','')?:seom_desc_for_post($id))).'">' . "\n";$img=seom_meta($id,'og_image',get_the_post_thumbnail_url($id,'full')?:seom_default_image());if($img)echo '<meta name="twitter:image" content="'.esc_url($img).'">' . "\n";}}
}
